-- =====================================================
-- FLORY — Migración + carga del catálogo de especies
-- 206 especies de Chile
--
-- Ejecutar DESPUÉS de flory_schema_final.sql
--
-- Parte A: ajusta el esquema al formato real de los datos
-- Parte B: carga las 206 especies
-- Parte C: verificación
-- =====================================================


-- =====================================================
-- PARTE A — AJUSTES AL ESQUEMA
--
-- Tres campos venían como booleanos y los datos traen
-- tres estados. Convertirlos a boolean perdería información
-- relevante, en un caso incluso peligrosa:
--
--   suitable_outdoor : no / semisombra_protegida / si
--   frost_sensitive  : si / parcial / no
--   toxic_to_pets    : si / no / no_listado
--
-- El tercero importa de verdad: "no listado en ASPCA" NO
-- significa "seguro para mascotas". Son 44 especies. Decirle
-- a alguien que su gato puede masticarla sin riesgo, cuando
-- en realidad nadie lo ha evaluado, es el tipo de error que
-- no se arregla con una disculpa.
-- =====================================================

create type plant_category      as enum ('interior', 'exterior_maceta', 'suculenta_cactus');
create type outdoor_suitability as enum ('no', 'semisombra_protegida', 'si');
create type frost_tolerance     as enum ('si', 'parcial', 'no');
create type pet_toxicity        as enum ('si', 'no', 'no_listado_aspca');
create type data_confidence     as enum ('alta', 'media', 'baja');

alter table species
  drop column suitable_outdoor,
  drop column frost_sensitive,
  drop column toxic_to_pets;

alter table species
  add column category           plant_category not null default 'interior',
  add column suitable_outdoor   outdoor_suitability not null default 'no',
  add column frost_sensitive    frost_tolerance not null default 'si',
  add column toxic_to_pets      pet_toxicity not null default 'no_listado_aspca',

  -- Trazabilidad: de dónde salió el intervalo de riego y qué tan
  -- confiable es. Permite priorizar qué corregir con datos reales.
  add column watering_confidence data_confidence not null default 'media',
  add column watering_source     text,
  add column care_archetype      text,
  add column verified_cl         boolean default false;

create index species_category_idx  on species(category);
create index species_archetype_idx on species(care_archetype);
create index species_lowconf_idx   on species(watering_confidence)
  where watering_confidence = 'baja';

comment on column species.toxic_to_pets is
  'no_listado_aspca NO equivale a "no toxica": significa que ASPCA no la ha evaluado. La app debe decirlo asi.';
comment on column species.watering_confidence is
  'Confianza del intervalo de riego. Las de confianza baja son las primeras a corregir con feedback real.';


-- =====================================================
-- PARTE B — CARGA DE LAS 206 ESPECIES
-- =====================================================

insert into species (
  scientific_name, common_name, aliases, category,
  base_watering_days, min_watering_days, max_watering_days,
  watering_confidence, watering_source, care_archetype,
  light_need, suitable_outdoor, frost_sensitive, toxic_to_pets,
  common_problems, verified_cl, prompt_context
) values
  ('Adiantum raddianum', 'Culantrillo', array['helecho culantrillo', 'adianto', 'cabello de Venus'], 'interior', 3, 2, 6, 'media', 'Arquetipo ''helecho_humedo'' — Base interior CL (greengrowshop 5-7d verano) ajustada a la baja: grupo mas sediento', 'helecho_humedo', 'baja', 'no', 'si', 'no', '["frondas cafes y quebradizas por aire seco", "caida de hojitas", "amarillamiento por sol directo", "sustrato hidrofobico si se seco del todo"]'::jsonb, false, 'Culantrillo (Adiantum raddianum). Planta de interior. Riego de referencia cada 3 dias (rango seguro 2-6). Requiere poca luz. No apta para intemperie, muy sensible a heladas. Problemas frecuentes: frondas cafes y quebradizas por aire seco; caida de hojitas; amarillamiento por sol directo; sustrato hidrofobico si se seco del todo.'),
