-- =====================================================
-- PARTE C — VERIFICACIÓN
-- Correr después de la carga. Los cuatro primeros deben dar 0.
-- =====================================================

-- 1. Intervalos incoherentes (debe dar 0)
select count(*) as intervalos_invalidos from species
where not (min_watering_days <= base_watering_days
           and base_watering_days <= max_watering_days
           and min_watering_days >= 1);

-- 2. Interior marcada como apta para intemperie sin protección (debe dar 0)
select count(*) as interior_a_la_intemperie from species
where category = 'interior' and suitable_outdoor = 'si' and frost_sensitive = 'si';

-- 3. Sin alias, rompe el buscador (debe dar 0)
select count(*) as sin_alias from species where cardinality(aliases) = 0;

-- 4. Sin problemas comunes, deja al diagnóstico sin contexto (debe dar 0)
select count(*) as sin_problemas from species where jsonb_array_length(common_problems) = 0;

-- 5. Panorama del catálogo
select category, count(*) as especies,
       count(*) filter (where verified_cl) as verificadas,
       count(*) filter (where watering_confidence = 'baja') as confianza_baja,
       count(*) filter (where toxic_to_pets = 'si') as toxicas,
       count(*) filter (where toxic_to_pets = 'no_listado_aspca') as sin_datos_toxicidad,
       round(avg(base_watering_days), 1) as riego_promedio
from species group by category order by especies desc;

-- 6. Las 16 de confianza baja: primeras a corregir
select common_name, scientific_name, base_watering_days, care_archetype
from species where watering_confidence = 'baja'
order by category, common_name;

-- 7. Probar el buscador con errores de tipeo y sin tildes
select * from find_species('potos');
select * from find_species('costilla');
select * from find_species('arbol de jade');